import React,{useEffect,useMemo,useState}from'react';import{createRoot}from'react-dom/client';import{Search,Plus,Edit,Trash2,Eye,Upload,X,Menu,LogOut,LayoutDashboard,FolderKanban,MessageSquare,Users,Settings as SettingsIcon,Briefcase,Palette,ChevronRight,CheckCircle,ExternalLink,Sun,Moon,Shield,Image as ImageIcon}from'lucide-react';import'./style.css';import{AUTH_KEY,demoData,enquiryFlow,loadData,saveData,workflow}from'./data';import{AppData,Category,ContentItem,Enquiry,EnquiryStatus,Project,ProjectStatus,Service,TeamMember}from'./types';import{changeCurrentUserPassword,createSupabaseEnquiry,isSupabaseConfigured,loadAdminSupabaseData,loadClientSupabaseData,loadPublicSupabaseData,ensureClientProfile,getCurrentUserRole,loadTeamSupabaseData,registerClientAccount,sendPasswordRecovery,saveSupabaseProject,getOwnTeamMemberProfile,saveOwnTeamMemberProfile,signInSuperAdmin,signInWithGoogle,signOutSupabase,syncCloudData,uploadToSupabaseStorage}from'./supabaseApi';
const cats:('All'|Category)[]=['All','Websites','App UI/UX','YouTube Thumbnails','Posters','Social Media Creatives','Branding'];const statuses:ProjectStatus[]=['Draft','Enquiry','Quotation Sent','Approved','In Progress','Review','Changes Requested','Delivered','Archived'];const eqStatuses:EnquiryStatus[]=['New Enquiry','Enquiry Review','Quotation Sent','Client Approved','Project Created','Project In Progress','Client Review','Changes Requested','Final Delivery','Completed'];
function socialDefaults(){return{linkedin:'',github:'',instagram:'',facebook:'',twitter:'',youtube:'',behance:'',dribbble:'',website:'',portfolio:'',whatsapp:'',email:'',resume:''}}
function normalizeUrl(v:string,kind='url'){v=(v||'').trim();if(!v)return'';if(kind==='email')return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)?v:'';if(kind==='whatsapp')return v.replace(/[^+0-9]/g,'');if(!/^https?:\/\//i.test(v))v='https://'+v;try{new URL(v);return v}catch{return''}}
function BrandIcon({k}:any){const common={width:20,height:20,viewBox:'0 0 24 24',fill:'currentColor','aria-hidden':'true'} as any;const path:any={linkedin:'M4.98 3.5C4.98 4.88 3.86 6 2.5 6S0 4.88 0 3.5 1.12 1 2.5 1s2.48 1.12 2.48 2.5zM.35 8h4.3v14H.35V8zm7.3 0h4.12v1.91h.06c.57-1.08 1.97-2.22 4.06-2.22 4.34 0 5.14 2.86 5.14 6.58V22h-4.3v-6.85c0-1.63-.03-3.73-2.27-3.73-2.28 0-2.63 1.78-2.63 3.61V22H7.65V8z',github:'M12 .5a12 12 0 0 0-3.79 23.39c.6.11.82-.26.82-.58v-2.04c-3.34.73-4.04-1.61-4.04-1.61-.55-1.39-1.34-1.76-1.34-1.76-1.09-.75.08-.74.08-.74 1.21.09 1.85 1.24 1.85 1.24 1.07 1.84 2.81 1.31 3.5 1 .11-.78.42-1.31.76-1.61-2.67-.3-5.47-1.33-5.47-5.93 0-1.31.47-2.38 1.24-3.22-.12-.3-.54-1.52.12-3.18 0 0 1.01-.32 3.3 1.23a11.5 11.5 0 0 1 6 0c2.29-1.55 3.3-1.23 3.3-1.23.66 1.66.24 2.88.12 3.18.77.84 1.24 1.91 1.24 3.22 0 4.61-2.81 5.62-5.49 5.92.43.37.81 1.1.81 2.22v3.29c0 .32.22.7.83.58A12 12 0 0 0 12 .5z',youtube:'M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.6 12 3.6 12 3.6s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2 31 31 0 0 0 0 12a31 31 0 0 0 .5 5.8 3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1A31 31 0 0 0 24 12a31 31 0 0 0-.5-5.8zM9.6 15.5v-7l6.2 3.5-6.2 3.5z',whatsapp:'M20.5 3.5A11.8 11.8 0 0 0 1.9 17.8L.5 23.5l5.8-1.5A11.8 11.8 0 0 0 20.5 3.5zM12.1 21a9.1 9.1 0 0 1-4.6-1.3l-.3-.2-3.4.9.9-3.3-.2-.3A9.2 9.2 0 1 1 12.1 21zm5-6.8c-.3-.1-1.7-.8-2-.9-.3-.1-.5-.1-.7.2-.2.3-.8.9-1 .1-.2.2-.4.2-.7.1a7.5 7.5 0 0 1-2.2-1.4 8.3 8.3 0 0 1-1.5-1.9c-.2-.3 0-.5.1-.7l.5-.6c.1-.2.2-.3.3-.5.1-.2 0-.4 0-.5l-.9-2c-.2-.5-.5-.4-.7-.4h-.6c-.2 0-.5.1-.8.4-.3.3-1 1-1 2.4s1 2.8 1.2 3c.1.2 2 3.1 4.9 4.3.7.3 1.2.5 1.6.6.7.2 1.3.2 1.8.1.6-.1 1.7-.7 1.9-1.3.2-.6.2-1.2.2-1.3-.1-.1-.3-.2-.5-.3z'};if(path[k])return <svg {...common}><path d={path[k]}/></svg>;if(k==='email')return <svg {...common} viewBox="0 0 24 24"><path d="M2 5h20v14H2V5zm2 3.2V17h16V8.2l-8 5-8-5zm16-1.2H4l8 5 8-5z"/></svg>;if(k==='portfolio'||k==='website')return <svg {...common} viewBox="0 0 24 24"><path d="M3 5h18v14H3V5zm2 2v10h14V7H5zm3 12h8v2H8v-2z"/></svg>;return <span>{socialMeta[k]?.[0]||k}</span>}const socialMeta:any={linkedin:['in','LinkedIn'],github:['GH','GitHub'],instagram:['IG','Instagram'],facebook:['f','Facebook'],twitter:['X','X / Twitter'],youtube:['YT','YouTube'],behance:['Be','Behance'],dribbble:['Db','Dribbble'],website:['Web','Personal Website'],portfolio:['Port','Portfolio'],whatsapp:['WA','WhatsApp'],email:['@','Email'],resume:['CV','Resume/CV']};
function memberUrl(m:TeamMember,k:string){const v=(m.socials as any)?.[k]||'';if(k==='email')return v?'mailto:'+v:'';if(k==='whatsapp')return v?'https://wa.me/'+v.replace(/[^0-9]/g,''):'';return v}function paymentUrl(settings:any,enquiry?:Enquiry,amount?:number){const note=encodeURIComponent(enquiry?.number||'EduCoder payment');if(settings.paymentLink)return settings.paymentLink;if(settings.upiId){const pa=encodeURIComponent(settings.upiId),pn=encodeURIComponent(settings.paymentMerchant||settings.businessName||'EduCoder Coding Hub');return `upi://pay?pa=${pa}&pn=${pn}&am=${amount||''}&cu=INR&tn=${note}`}return ''}
function blankProject():Project{return{id:crypto.randomUUID(),title:'',category:'Websites',coverImage:'',galleryImages:[],clientName:'',year:new Date().getFullYear(),description:'',problem:'',process:'',result:'',tools:[],tags:[],link:'',featured:false,published:false,status:'Draft',order:999,revenue:0,deadline:'',updates:[]}}function blankService():Service{return{id:crypto.randomUUID(),name:'',icon:'Sparkles',description:'',price:'',deliveryTime:'',deliverables:[],active:true,order:999}}function blankMember():TeamMember{return{id:crypto.randomUUID(),username:'',photo:'',name:'',fullName:'',role:'',bio:'',shortBio:'',longBio:'',skills:[],experience:'',location:'',email:'',phone:'',socials:socialDefaults(),projects:[],active:true,featured:false,order:999,joinDate:new Date().toISOString().slice(0,10),availability:'Available',resumeUrl:''}}function imgPlaceholder(t:string){return`data:image/svg+xml;utf8,${encodeURIComponent(`<svg xmlns='http://www.w3.org/2000/svg' width='1000' height='700'><defs><linearGradient id='g' x1='0' x2='1'><stop stop-color='#06b6d4'/><stop offset='1' stop-color='#7c3aed'/></linearGradient></defs><rect width='100%' height='100%' fill='#070b1a'/><circle cx='250' cy='180' r='240' fill='url(#g)' opacity='.5'/><text x='70' y='380' font-size='58' font-family='Arial' fill='white' font-weight='800'>${t||'Creative Upload'}</text></svg>`)}`}
function demoProject():Project{const p=blankProject();p.title='EduCoder Coding Hub Website';p.category='Websites';p.coverImage=imgPlaceholder('EduCoder Coding Hub');p.galleryImages=[imgPlaceholder('Landing Page'),imgPlaceholder('Admin Dashboard'),imgPlaceholder('Client Portal')];p.clientName='EduCoder Coding Hub';p.year=2026;p.description='A complete premium portfolio and business management platform with public showcase, client enquiries, team dashboard, payments and role-based admin management.';p.problem='The business needed one central platform to showcase creative services, capture client enquiries, manage projects, team profiles and payment workflows across devices.';p.process='Brand system, dark glassmorphism UI, responsive layouts, Supabase Auth, dashboard flows, enquiry workflow, media uploads and GitHub Pages deployment.';p.result='Delivered a production-style creator studio platform with public portfolio, secure role dashboards, Supabase cloud data and payment link support.';p.tools=['React','TypeScript','Supabase','GitHub Pages','CSS'];p.tags=['educoder','website','dashboard','supabase','portfolio'];p.link='https://manpreetsingh13-coder.github.io/educoder-coding-hub/';p.featured=true;p.published=true;p.status='Delivered';p.order=0;p.revenue=25000;p.deadline='2026-08-30';p.updates=[{date:'2026-08-01',status:'Approved',note:'Platform scope approved'},{date:'2026-08-14',status:'Delivered',note:'Demo project added'}];return p}
function fileToData(file:File,max=3*1024*1024){return new Promise<string>((res,rej)=>{if(!file.type.startsWith('image/'))return rej('Only image files allowed');if(file.size>max)return rej('File must be below 3MB');const r=new FileReader();r.onload=()=>res(String(r.result));r.onerror=()=>rej('Upload failed');r.readAsDataURL(file)})}
function App(){const[data,setData]=useState<AppData>(()=>loadData());const[page,setPage]=useState('home');const[auth,setAuth]=useState(()=>localStorage.getItem(AUTH_KEY)==='true');const[role,setRole]=useState(()=>localStorage.getItem('ech_role')||'super_admin');const[toast,setToast]=useState('');useEffect(()=>{if(isSupabaseConfigured)loadPublicSupabaseData(loadData()).then(setData).catch(()=>setToast('Supabase load failed; showing local data'))},[]);useEffect(()=>{if(!isSupabaseConfigured)return;getCurrentUserRole().then(async r=>{if(!r)return;await ensureClientProfile();localStorage.setItem('ech_role',r);setRole(r);setAuth(true);localStorage.setItem(AUTH_KEY,'true');const cloud=r==='client'?await loadClientSupabaseData(loadData()):r==='team_member'?await loadTeamSupabaseData(loadData()):await loadAdminSupabaseData(loadData());setData(cloud);setPage('admin')}).catch(()=>{})},[]);useEffect(()=>{saveData(data)},[data]);useEffect(()=>{if(!auth||!isSupabaseConfigured)return;const t=setTimeout(()=>syncCloudData(data).catch(()=>setToast('Cloud sync failed. Check Supabase RLS/Auth policies.')),900);return()=>clearTimeout(t)},[data,auth]);useEffect(()=>{document.body.className=data.settings.theme},[data.settings.theme]);const update=(fn:(d:AppData)=>AppData)=>setData(d=>{const nd=fn({...d,activity:[...d.activity]});return nd});const notify=(m:string)=>{setToast(m);setTimeout(()=>setToast(''),2800)};return <><Nav page={page} setPage={setPage} data={data} auth={auth}/>{toast&&<div className="toast">{toast}</div>}<main>{page==='home'&&<Home data={data} setPage={setPage}/>} {page==='showcase'&&<Showcase data={data}/>} {page==='services'&&<Services data={data} setPage={setPage}/>} {page==='team'&&<Team data={data}/>} {page==='contact'&&<Contact data={data} update={update} notify={notify} auth={auth} setPage={setPage}/>} {page==='login'&&<Login setAuth={v=>{setAuth(v);localStorage.setItem(AUTH_KEY,String(v));setPage('admin')}} setRole={setRole} setData={setData} notify={notify}/>} {page==='admin'&&(auth?(role==='client'?<ClientDashboard data={data} update={update} notify={notify} logout={()=>{signOutSupabase();setAuth(false);localStorage.removeItem(AUTH_KEY);localStorage.removeItem('ech_role');setPage('home')}}/>:role==='team_member'?<TeamDashboard data={data} update={update} notify={notify} logout={()=>{signOutSupabase();setAuth(false);localStorage.removeItem(AUTH_KEY);localStorage.removeItem('ech_role');setPage('home')}}/>:<Admin data={data} update={update} notify={notify} logout={()=>{signOutSupabase();setAuth(false);localStorage.removeItem(AUTH_KEY);localStorage.removeItem('ech_role');setPage('home')}}/>):<Login setAuth={v=>{setAuth(v);localStorage.setItem(AUTH_KEY,String(v))}} setRole={setRole} setData={setData} notify={notify}/>)}</main><Footer data={data}/></>}
function Nav({page,setPage,data,auth}:any){const[open,setOpen]=useState(false);const items=['home','showcase','services','team','contact'];return <header className="nav"><button className="brand" onClick={()=>setPage('home')}><span>{String(data.settings.logo||'').startsWith('data:')||String(data.settings.logo||'').startsWith('http')?<img className="logoImg" src={data.settings.logo}/>:data.settings.logo}</span><b>{data.settings.businessName}</b></button><button className="hamb" onClick={()=>setOpen(!open)}><Menu/></button><div className={'links '+(open?'show':'')}>{items.map(i=><button className={page===i?'active':''} onClick={()=>{setPage(i);setOpen(false)}} key={i}>{i}</button>)}<button onClick={()=>setPage(auth?'admin':'login')} className="adminBtn"><Shield size={16}/>Admin</button></div></header>}
function Home({data,setPage}:any){return <section className="hero"><div className="orb o1"></div><div className="orb o2"></div><div className="heroText"><p className="pill">Build it. Show it. Grow it.</p><h1>Creative work that makes your brand impossible to ignore.</h1><p>EduCoder Coding Hub designs websites, apps, thumbnails, posters and digital brands with premium strategy and sharp execution.</p><div><button className="primary" onClick={()=>setPage('showcase')}>View Our Work</button><button className="secondary" onClick={()=>setPage('contact')}>Start a Project</button></div></div><div className="heroCard"><img src={data.projects[0]?.coverImage}/><h3>Featured Studio Board</h3><p>{data.projects.filter((p:Project)=>p.published).length} published case studies - {data.services.filter((s:Service)=>s.active).length} services</p></div><Section title="Featured work"><ProjectGrid projects={data.projects.filter((p:Project)=>p.featured&&p.published).slice(0,4)}/></Section><Section title="Services preview"><div className="grid cards">{data.services.filter((s:Service)=>s.active).slice(0,4).map((s:Service)=><Card key={s.id}><h3>{s.name}</h3><p>{s.description}</p><b>{s.price}</b></Card>)}</div></Section><Section title="Team preview"><TeamCards team={data.team.filter((m:TeamMember)=>m.active).slice(0,3)}/></Section><div className="cta"><h2>Ready to launch a better visual identity?</h2><button className="primary" onClick={()=>setPage('contact')}>Send Enquiry</button></div></section>}
function Section(p:any){return <section className="section"><h2>{p.title}</h2>{p.children}</section>}function Card(p:any){return <div className="card">{p.children}</div>}
function ProjectGrid({projects}:{projects:Project[]}){const[sel,setSel]=useState<Project|null>(null);return <>{projects.length? <div className="grid projects">{projects.sort((a,b)=>a.order-b.order).map(p=><button className="project" onClick={()=>setSel(p)} key={p.id}><img src={p.coverImage||imgPlaceholder(p.title)}/><span>{p.category}</span><h3>{p.title}</h3><p>{p.tags.join(' - ')}</p></button>)}</div>:<Empty text="No published projects match this view."/>}{sel&&<ProjectModal p={sel} close={()=>setSel(null)}/>}</>}
function Showcase({data}:any){const[cat,setCat]=useState<any>('All'),[q,setQ]=useState(''),[load,setLoad]=useState(true);useEffect(()=>{const t=setTimeout(()=>setLoad(false),350);return()=>clearTimeout(t)},[]);const ps=data.projects.filter((p:Project)=>p.published&&(cat==='All'||p.category===cat)&&(`${p.title} ${p.tags.join(' ')}`.toLowerCase().includes(q.toLowerCase())));return <Page title="Showcase" sub="Browse websites, UI/UX, thumbnails, posters, social creatives and branding."><div className="toolbar"><div className="search"><Search/><input placeholder="Search projects or tags" value={q} onChange={e=>setQ(e.target.value)}/></div><select value={cat} onChange={e=>setCat(e.target.value)}>{cats.map(c=><option>{c}</option>)}</select></div><h2>Featured Projects</h2><ProjectGrid projects={data.projects.filter((p:Project)=>p.featured&&p.published)}/><h2>All Projects</h2>{load?<div className="loading">Loading showcase...</div>:<ProjectGrid projects={ps}/>}</Page>}
function ProjectModal({p,close}:{p:Project,close:()=>void}){const[light,setLight]=useState('');useEffect(()=>{const h=(e:KeyboardEvent)=>{if(e.key==='Escape')close()};addEventListener('keydown',h);return()=>removeEventListener('keydown',h)},[]);return <div className="modalBack" onMouseDown={close}><div className="modal big" onMouseDown={e=>e.stopPropagation()}><button className="close" onClick={close}><X/></button><img className="wide" src={p.coverImage||imgPlaceholder(p.title)}/><h2>{p.title}</h2><p className="pill">{p.category} - {p.clientName} - {p.year}</p><p>{p.description}</p><div className="cols"><Card><h3>Problem solved</h3><p>{p.problem}</p></Card><Card><h3>Design process</h3><p>{p.process}</p></Card><Card><h3>Final result</h3><p>{p.result}</p></Card></div><Timeline status={p.status}/><div className="chips">{p.tools.map(t=><span>{t}</span>)}{p.tags.map(t=><span>#{t}</span>)}</div><div className="thumbs">{p.galleryImages.map(g=><img onClick={()=>setLight(g)} src={g}/>)}</div><a className="primary inline" href={p.link||'#'} target="_blank">Open project <ExternalLink size={16}/></a></div>{light&&<div className="light" onClick={()=>setLight('')}><img src={light}/></div>}</div>}
function Timeline({status}:{status:ProjectStatus}){const idx=workflow.indexOf(status);return <div className="timeline">{workflow.slice(0,8).map((s,i)=><div className={i<=idx?'done':''}><span>{i<=idx?<CheckCircle size={16}/>:i+1}</span><small>{s}</small></div>)}</div>}
function Services({data,setPage}:any){return <Page title="Services" sub="Clear deliverables, transparent starting prices and fast delivery."><div className="grid cards">{data.services.filter((s:Service)=>s.active).sort((a,b)=>a.order-b.order).map((s:Service)=><Card key={s.id}><Briefcase/><h3>{s.name}</h3><p>{s.description}</p><h2>{s.price}</h2><p>{s.deliveryTime}</p><ul>{s.deliverables.map(d=><li>{d}</li>)}</ul><button className="primary" onClick={()=>setPage('contact')}>Request this service</button></Card>)}</div></Page>}
function Team({data}:any){return <Page title="EduCoder Coding Hub Team" sub="Professional creative profiles with verified social accounts, skills, availability and related showcase work."><TeamCards team={data.team.filter((m:TeamMember)=>m.active).sort((a,b)=>a.order-b.order)} projects={data.projects}/></Page>}
function SocialIcons({m}:any){return <div className="socials">{Object.keys(socialMeta).map(k=>{const href=memberUrl(m,k);if(!href)return null;return <a key={k} href={href} target="_blank" rel="noreferrer" aria-label={`${socialMeta[k][1]} for ${m.fullName||m.name}`} title={socialMeta[k][1]}><BrandIcon k={k}/></a>})}</div>}
function TeamCards({team,projects=[]}:any){const[sel,setSel]=useState<TeamMember|null>(null);return <>{team.length?<div className="grid cards teamGrid">{team.map((m:TeamMember)=>{const done=projects.filter((p:Project)=>m.projects.includes(p.id)||p.assignedTo===m.id||p.status==='Delivered').length;return <Card key={m.id}><div className="teamCard"><img loading="lazy" className="avatar" src={m.photo||imgPlaceholder(m.fullName||m.name)}/><span className={'avail '+String(m.availability).toLowerCase().replace(/ /g,'-')}>{m.availability}</span><h3>{m.fullName||m.name}</h3><b>{m.role}</b><p>{m.shortBio||m.bio}</p><div className="chips">{m.skills.map(s=><span>{s}</span>)}</div><p className="muted">{done} completed projects</p><SocialIcons m={m}/><button className="primary" onClick={()=>setSel(m)}>View Profile</button>{(m.email||m.socials.email)&&<a className="secondary inline" href={'mailto:'+(m.email||m.socials.email)}>Contact Member</a>}</div></Card>})}</div>:<Empty text="No visible team members yet."/>}{sel&&<TeamProfileModal m={sel} projects={projects} close={()=>setSel(null)}/>}</>}
function TeamProfileModal({m,projects,close}:any){const related=projects.filter((p:Project)=>m.projects.includes(p.id)||p.assignedTo===m.id);return <Modal close={close}><div className="profileHero"><img loading="lazy" src={m.photo||imgPlaceholder(m.fullName||m.name)}/><div><p className="pill">{m.availability}</p><h2>{m.fullName||m.name}</h2><h3>{m.role}</h3><p>{m.longBio||m.bio||m.shortBio}</p></div></div><div className="cols"><Card><h3>About</h3><p>{m.location&&`Location: ${m.location}`}</p><p>{m.experience&&`Experience: ${m.experience}`}</p><p>{m.joinDate&&`Joined: ${m.joinDate}`}</p></Card><Card><h3>Skills</h3><div className="chips">{m.skills.map((x:string)=><span>{x}</span>)}</div></Card><Card><h3>Projects completed</h3><h2>{related.length}</h2></Card></div><h3>Related showcase projects</h3><div className="chips">{related.length?related.map((p:Project)=><span>{p.title}</span>):<span>No assigned public projects yet</span>}</div><h3>Accounts</h3><SocialIcons m={m}/><div className="profileActions">{memberUrl(m,'resume')&&<a className="primary inline" href={memberUrl(m,'resume')} target="_blank" rel="noreferrer">Download Resume</a>}{(m.email||m.socials.email)&&<a className="secondary inline" href={'mailto:'+(m.email||m.socials.email)}>Email</a>}{memberUrl(m,'whatsapp')&&<a className="secondary inline" href={memberUrl(m,'whatsapp')} target="_blank" rel="noreferrer">WhatsApp</a>}</div></Modal>}
function Contact({data,update,notify,auth,setPage}:any){const[e,setE]=useState<any>({name:'',email:'',phone:'',business:'',service:data.services[0]?.name||'',budget:'',deadline:'',description:'',file:''});const[err,setErr]=useState('');if(!auth)return <Page title="Client Login Required" sub="Please login before sending an enquiry. This keeps your project requests secure and lets you track them from your client dashboard."><div className="cta"><h2>Login to send your enquiry</h2><button className="primary" onClick={()=>setPage('login')}>Login / Create Supabase Client</button></div></Page>;async function sub(ev:any){ev.preventDefault();if(!e.name||!/\S+@\S+\.\S+/.test(e.email)||!e.phone||!e.service||e.description.length<15){setErr('Please fill name, valid email, phone, service and at least 15 characters description.');return}const en:Enquiry={...e,id:crypto.randomUUID(),number:'ECH-'+Date.now().toString().slice(-6),status:'New Enquiry',notes:[],createdAt:new Date().toISOString()};try{if(isSupabaseConfigured)await createSupabaseEnquiry(en)}catch(x){setErr('Supabase save failed. '+String((x as any).message||x));return}update((d:AppData)=>({...d,enquiries:[en,...d.enquiries],notifications:[{id:crypto.randomUUID(),message:`New enquiry ${en.number} from ${en.name}`,date:new Date().toISOString(),read:false},...d.notifications],activity:[`Enquiry ${en.number} submitted`,...d.activity]}));setE({name:'',email:'',phone:'',business:'',service:data.services[0]?.name||'',budget:'',deadline:'',description:'',file:''});setErr('');notify(`Success! Your enquiry number is ${en.number}`)}return <Page title="Client Enquiry" sub="Submit your project request. It will be saved in Supabase and visible to the team dashboard."><form className="form" onSubmit={sub}>{err&&<p className="error">{err}</p>} {['name','email','phone','business','budget','deadline'].map(k=><label>{k}<input type={k==='deadline'?'date':'text'} value={e[k]} onChange={ev=>setE({...e,[k]:ev.target.value})}/></label>)}<label>Required service<select value={e.service} onChange={ev=>setE({...e,service:ev.target.value})}>{data.services.map((s:Service)=><option>{s.name}</option>)}</select></label><label>Project description<textarea value={e.description} onChange={ev=>setE({...e,description:ev.target.value})}/></label><label>File upload<input type="file" accept="image/*" onChange={async ev=>{try{const f=ev.target.files?.[0];if(f)setE({...e,file:await fileToData(f)})}catch(x){setErr(String(x))}}}/></label>{e.file&&<img className="preview" src={e.file}/>}<button className="primary">Submit Enquiry</button></form></Page>}
function Login({setAuth,setRole,setData,notify}:any){const ADMIN_CFG='ech_admin_config_v1';const saved=()=>{try{return JSON.parse(localStorage.getItem(ADMIN_CFG)||'null')}catch{return null}};const[cfg,setCfg]=useState<any>(()=>saved());const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[mode,setMode]=useState<'login'|'register'|'forgot'>('login'),[clientName,setClientName]=useState(''),[setup,setSetup]=useState({email:'',password:'',confirm:''});const[busy,setBusy]=useState(false);function hash(v:string){return btoa(unescape(encodeURIComponent(v))).split('').reverse().join('')}async function googleLogin(){try{setBusy(true);await signInWithGoogle()}catch(x){notify(String((x as any).message||x));setBusy(false)}}async function forgotPassword(e:any){e.preventDefault();try{setBusy(true);await sendPasswordRecovery(email);notify('Password recovery link sent. Check your email.')}catch(x){notify(String((x as any).message||x))}finally{setBusy(false)}}async function cloudLogin(e:any){e.preventDefault();try{setBusy(true);const session=await signInSuperAdmin(email.trim().toLowerCase(),password);const userRole=(session as any).role||'team_member';localStorage.setItem('ech_role',userRole);setRole(userRole);const cloud=userRole==='client'?await loadClientSupabaseData(loadData()):userRole==='team_member'?await loadTeamSupabaseData(loadData()):await loadAdminSupabaseData(loadData());setData(cloud);setAuth(true);notify(userRole==='client'?'Client dashboard loaded':userRole==='team_member'?'Team dashboard loaded':'Supabase Super Admin logged in. Cloud data loaded.')}catch(x){notify(String((x as any).message||x))}finally{setBusy(false)}}async function clientRegister(e:any){e.preventDefault();try{setBusy(true);if(!clientName.trim()||!/\S+@\S+\.\S+/.test(email)||password.length<8){notify('Enter name, valid email and password with 8+ characters');return}await registerClientAccount(clientName.trim(),email.trim().toLowerCase(),password);notify('Client account created. If email confirmation is enabled, verify your email, then login.');setMode('login')}catch(x){notify(String((x as any).message||x))}finally{setBusy(false)}}function createAdmin(e:any){e.preventDefault();if(isSupabaseConfigured){notify('Use Supabase Auth login for cross-device data.');return}if(!/\S+@\S+\.\S+/.test(setup.email)||setup.password.length<8||setup.password!==setup.confirm){notify('Use valid email and matching password with 8+ characters');return}const next={email:setup.email.trim().toLowerCase(),passwordHash:hash(setup.password)};localStorage.setItem(ADMIN_CFG,JSON.stringify(next));setCfg(next);setSetup({email:'',password:'',confirm:''});notify('Local Super Admin account created')}function localLogin(e:any){e.preventDefault();if(cfg&&email.trim().toLowerCase()===cfg.email&&hash(password)===cfg.passwordHash){setAuth(true);notify('Logged in locally')}else notify('Invalid login')}if(isSupabaseConfigured)return <Page title={mode==='register'?'Client Register':mode==='forgot'?'Recover Password':'Login'} sub={mode==='register'?'Create a client account to send and track enquiries.':mode==='forgot'?'Enter your account email. We will send a secure password reset link.':'Client, team member and super admin login. Enquiries are locked until login.'}><form className="form small" onSubmit={mode==='login'?cloudLogin:mode==='register'?clientRegister:forgotPassword}>{mode==='register'&&<label>Full name<input value={clientName} onChange={e=>setClientName(e.target.value)}/></label>}<label>Email<input value={email} onChange={e=>setEmail(e.target.value)}/></label>{mode!=='forgot'&&<label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)}/></label>}<button className="primary" disabled={busy}>{busy?'Please wait...':mode==='login'?'Login':mode==='register'?'Create Client Account':'Send Recovery Link'}</button>{mode==='login'&&<button type="button" className="secondary" onClick={googleLogin}>Continue with Google</button>}{mode==='login'&&<button type="button" className="secondary" onClick={()=>setMode('forgot')}>Forgot password?</button>}<button type="button" className="secondary" onClick={()=>setMode(mode==='login'?'register':'login')}>{mode==='login'?'New client? Register':'Back to Login'}</button></form></Page>;if(!cfg)return <Page title="Create Local Super Admin" sub="Local fallback only. For cross-device data use Supabase login."><form className="form small" onSubmit={createAdmin}><label>Super Admin email<input value={setup.email} onChange={e=>setSetup({...setup,email:e.target.value})}/></label><label>Password<input type="password" value={setup.password} onChange={e=>setSetup({...setup,password:e.target.value})}/></label><label>Confirm password<input type="password" value={setup.confirm} onChange={e=>setSetup({...setup,confirm:e.target.value})}/></label><button className="primary">Create Local Admin</button></form></Page>;return <Page title="Local Super Admin Login" sub="Local fallback mode."><form className="form small" onSubmit={localLogin}><label>Email<input value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="primary">Login</button></form></Page>}
function PasswordBox({notify}:any){const[p,setP]=useState({newPassword:'',confirm:''});const[busy,setBusy]=useState(false);async function save(){try{if(p.newPassword.length<8){notify('Password must be at least 8 characters');return}if(p.newPassword!==p.confirm){notify('Passwords do not match');return}setBusy(true);await changeCurrentUserPassword(p.newPassword);setP({newPassword:'',confirm:''});notify('Password changed successfully')}catch(x){notify(String((x as any).message||x))}finally{setBusy(false)}}return <Card><h3>Change Password</h3><p className="muted">Update your login password securely through Supabase Auth.</p><div className="form"><label>New password<input type="password" value={p.newPassword} onChange={e=>setP({...p,newPassword:e.target.value})}/></label><label>Confirm password<input type="password" value={p.confirm} onChange={e=>setP({...p,confirm:e.target.value})}/></label></div><button className="primary" disabled={busy} onClick={save}>{busy?'Updating...':'Change Password'}</button></Card>}
function ClientDashboard({data,update,notify,logout}:any){const[tab,setTab]=useState('new');const[q,setQ]=useState('');const[amount,setAmount]=useState<any>({});const list=data.enquiries.filter((e:Enquiry)=>`${e.name} ${e.email} ${e.number} ${e.service}`.toLowerCase().includes(q.toLowerCase()));function pay(e:Enquiry){const url=paymentUrl(data.settings,e,Number(amount[e.id]||0));if(!url){notify('Payment link/UPI is not configured yet.');return}window.open(url,'_blank','noopener,noreferrer');update((d:AppData)=>({...d,enquiries:d.enquiries.map(x=>x.id===e.id?{...x,paymentStatus:'Payment Started',paymentAmount:Number(amount[e.id]||0)}:x)}));notify('Payment page opened')}return <div className="admin"><aside><button className={tab==='new'?'active':''} onClick={()=>setTab('new')}><Plus size={18}/>New Enquiry</button><button className={tab==='mine'?'active':''} onClick={()=>setTab('mine')}><MessageSquare size={18}/>My Enquiries</button><button className={tab==='payments'?'active':''} onClick={()=>setTab('payments')}><Briefcase size={18}/>Payments</button><button className={tab==='security'?'active':''} onClick={()=>setTab('security')}><Shield size={18}/>Password</button><button onClick={logout}><LogOut size={18}/>Logout</button></aside><section className="adminMain"><div className="head"><h1>Client Dashboard</h1></div>{tab==='new'&&<Contact data={data} update={update} notify={notify} auth={true} setPage={()=>{}}/>}{tab==='mine'&&<Crud title="My Enquiries" search={q} setSearch={setQ}>{list.map((e:Enquiry)=><Row key={e.id}><b>{e.number}</b><span>{e.service}</span><span>{e.status}</span><span>{e.deadline}</span><span>{e.paymentStatus||'Unpaid'}</span></Row>)}</Crud>}{tab==='payments'&&<Page title="Payments" sub="Pay using configured payment link or UPI. Amount can be entered from your quotation."><div className="grid cards">{list.map((e:Enquiry)=><Card key={e.id}><h3>{e.number}</h3><p>{e.service}</p><p>Status: {e.paymentStatus||'Unpaid'}</p><label>Amount INR<input value={amount[e.id]||e.paymentAmount||''} onChange={ev=>setAmount({...amount,[e.id]:ev.target.value})}/></label><button className="primary" onClick={()=>pay(e)}>Pay Now</button></Card>)}</div>{data.settings.paymentQrUrl&&<Card><h3>Payment QR</h3><img className="preview" src={data.settings.paymentQrUrl}/></Card>}</Page>}{tab==='security'&&<PasswordBox notify={notify}/>}</section></div>}
function TeamDashboard({data,update,notify,logout}:any){const[q,setQ]=useState(''),[status,setStatus]=useState('All'),[sel,setSel]=useState<Enquiry|null>(null),[tab,setTab]=useState('enquiries'),[profile,setProfile]=useState<TeamMember|null>(null),[err,setErr]=useState('');useEffect(()=>{getOwnTeamMemberProfile().then(p=>setProfile(p||blankMember())).catch(x=>setErr(String((x as any).message||x)))},[]);const list=data.enquiries.filter((e:Enquiry)=>(status==='All'||e.status===status)&&(`${e.name} ${e.email} ${e.number} ${e.service}`.toLowerCase().includes(q.toLowerCase())));async function saveProfile(){if(!profile)return;try{const saved=await saveOwnTeamMemberProfile(profile);if(!saved)throw new Error('Profile save failed');setProfile(saved);notify('Profile updated successfully');update((d:AppData)=>({...d,team:d.team.some(x=>x.id===saved.id)?d.team.map(x=>x.id===saved.id?saved:x):[saved,...d.team]}))}catch(x){setErr(String((x as any).message||x))}}return <div className="admin"><aside><button className={tab==='enquiries'?'active':''} onClick={()=>setTab('enquiries')}><MessageSquare size={18}/>Enquiries</button><button className={tab==='profile'?'active':''} onClick={()=>setTab('profile')}><Users size={18}/>My Profile</button><button className={tab==='security'?'active':''} onClick={()=>setTab('security')}><Shield size={18}/>Password</button><button onClick={logout}><LogOut size={18}/>Logout</button></aside><section className="adminMain"><div className="head"><h1>Team Member Dashboard</h1></div>{tab==='enquiries'&&<><div className="grid stats"><Card><small>Total enquiries</small><h2>{data.enquiries.length}</h2></Card><Card><small>Pending</small><h2>{data.enquiries.filter((e:Enquiry)=>!['Completed','Final Delivery'].includes(e.status)).length}</h2></Card></div><Crud title="All Enquiries" search={q} setSearch={setQ}><select value={status} onChange={e=>setStatus(e.target.value)}><option>All</option>{eqStatuses.map(s=><option>{s}</option>)}</select>{list.map((e:Enquiry)=><Row key={e.id}><b>{e.number}</b><span>{e.name}</span><span>{e.email}</span><span>{e.phone}</span><span>{e.service}</span><span>{e.status}</span><button onClick={()=>setSel(e)}><Eye/></button></Row>)}</Crud>{sel&&<Modal close={()=>setSel(null)}><h2>{sel.number}</h2><p><b>Name:</b> {sel.name}</p><p><b>Email:</b> {sel.email}</p><div className="cols"><Card><h3>Sender Details</h3><p><b>Name:</b> {sel.name}</p><p><b>Email:</b> {sel.email}</p><p><b>Phone:</b> {sel.phone}</p><p><b>Business:</b> {sel.business}</p></Card><Card><h3>Requirement</h3><p><b>Service:</b> {sel.service}</p><p><b>Budget:</b> {sel.budget}</p><p><b>Deadline:</b> {sel.deadline}</p><p><b>Status:</b> {sel.status}</p><p><b>Payment:</b> {sel.paymentStatus||'Unpaid'}</p><p><b>Amount:</b> {sel.paymentAmount||''}</p></Card></div><h3>Project Description</h3><p>{sel.description}</p>{sel.file&&<img className="preview" src={sel.file}/>}</Modal>}</>}{tab==='profile'&&profile&&<Page title="My Team Profile" sub="Update your public team profile details, social accounts, availability and resume.">{err&&<p className="error">{err}</p>}<div className="form"><label>Full name<input value={profile.fullName||profile.name} onChange={e=>setProfile({...profile,fullName:e.target.value,name:e.target.value})}/></label><label>Username<input value={profile.username} onChange={e=>setProfile({...profile,username:e.target.value})}/></label><label>Role<input value={profile.role} onChange={e=>setProfile({...profile,role:e.target.value})}/></label><label>Short bio<textarea value={profile.shortBio||profile.bio} onChange={e=>setProfile({...profile,shortBio:e.target.value,bio:e.target.value})}/></label><label>Long bio<textarea value={profile.longBio} onChange={e=>setProfile({...profile,longBio:e.target.value})}/></label><label>Skills comma<input value={profile.skills.join(', ')} onChange={e=>setProfile({...profile,skills:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})}/></label><label>Experience<input value={profile.experience} onChange={e=>setProfile({...profile,experience:e.target.value})}/></label><label>Location<input value={profile.location} onChange={e=>setProfile({...profile,location:e.target.value})}/></label><label>Phone<input value={profile.phone} onChange={e=>setProfile({...profile,phone:e.target.value})}/></label><label>Availability<select value={profile.availability} onChange={e=>setProfile({...profile,availability:e.target.value as any})}>{['Available','Busy','On Leave','Not Available'].map(x=><option>{x}</option>)}</select></label><UploadBox label="Profile photo" set={v=>setProfile({...profile,photo:v})}/><UploadAny label="Resume/CV" set={v=>setProfile({...profile,resumeUrl:v,socials:{...profile.socials,resume:v}})}/>{Object.keys(socialMeta).filter(k=>!['email','resume'].includes(k)).map(k=><label key={k}>{socialMeta[k][1]}<input value={(profile.socials as any)[k]||''} onChange={e=>setProfile({...profile,socials:{...profile.socials,[k]:e.target.value}})}/></label>)}<label><input type="checkbox" checked={profile.active} onChange={e=>setProfile({...profile,active:e.target.checked})}/> Show on public website</label></div><button className="primary" onClick={saveProfile}>Save My Profile</button></Page>}{tab==='security'&&<PasswordBox notify={notify}/>}</section></div>}
function Admin({data,update,notify,logout}:any){const[tab,setTab]=useState('overview');const nav=[['overview',LayoutDashboard],['projects',FolderKanban],['enquiries',MessageSquare],['team',Users],['services',Briefcase],['content',Palette],['settings',SettingsIcon],['security',Shield]];return <div className="admin"><aside>{nav.map(([n,I]:any)=><button className={tab===n?'active':''} onClick={()=>setTab(n)}><I size={18}/>{n}</button>)}<button onClick={logout}><LogOut size={18}/>Logout</button></aside><section className="adminMain">{tab==='overview'&&<Overview data={data}/>} {tab==='projects'&&<ProjectsAdmin data={data} update={update} notify={notify}/>} {tab==='enquiries'&&<EnquiriesAdmin data={data} update={update} notify={notify}/>} {tab==='team'&&<TeamAdmin data={data} update={update} notify={notify}/>} {tab==='services'&&<ServicesAdmin data={data} update={update} notify={notify}/>} {tab==='content'&&<ContentAdmin data={data} update={update} notify={notify}/>} {tab==='settings'&&<SettingsAdmin data={data} update={update} notify={notify}/>} {tab==='security'&&<Page title="Security" sub="Change your Supabase login password."><PasswordBox notify={notify}/></Page>}</section></div>}
function Overview({data}:any){const cards=[['Total projects',data.projects.length],['Published',data.projects.filter((p:Project)=>p.published).length],['Draft',data.projects.filter((p:Project)=>!p.published).length],['Enquiries',data.enquiries.length],['Pending',data.enquiries.filter((e:Enquiry)=>!['Completed','Final Delivery'].includes(e.status)).length],['Active team',data.team.filter((m:TeamMember)=>m.active).length],['Monthly revenue','Rs. '+data.projects.reduce((a:number,p:Project)=>a+p.revenue,0).toLocaleString('en-IN')]];return <><h1>Dashboard Overview</h1><div className="grid stats">{cards.map(c=><Card><small>{c[0]}</small><h2>{c[1]}</h2></Card>)}</div><div className="cols"><Card><h3>Project status chart</h3>{statuses.map(s=><Bar label={s} val={data.projects.filter((p:Project)=>p.status===s).length}/>)}</Card><Card><h3>Enquiry status chart</h3>{eqStatuses.slice(0,6).map(s=><Bar label={s} val={data.enquiries.filter((e:Enquiry)=>e.status===s).length}/>)}</Card><Card><h3>Recent activity</h3>{data.activity.slice(0,8).map((a:string)=><p>- {a}</p>)}<h3>Upcoming deadlines</h3>{data.projects.filter((p:Project)=>p.deadline).slice(0,5).map((p:Project)=><p>{p.deadline} â€” {p.title}</p>)}</Card></div></>}
function Bar({label,val}:any){return <p className="bar"><span style={{width:Math.max(8,val*18)+'%'}}></span>{label}: {val}</p>}
function ProjectsAdmin({data,update,notify}:any){const[edit,setEdit]=useState<Project|null>(null),[q,setQ]=useState('');const list=data.projects.filter((p:Project)=>p.title.toLowerCase().includes(q.toLowerCase()));return <Crud title="Project Management" onAdd={()=>setEdit(blankProject())} search={q} setSearch={setQ}><button className="secondary" onClick={async()=>{const p=demoProject();try{if(isSupabaseConfigured)await saveSupabaseProject(p);update((d:AppData)=>d.projects.some(x=>x.title===p.title)?d:{...d,projects:[p,...d.projects],activity:[`Added demo project ${p.title}`,...d.activity]});notify("Demo project added")}catch(x){notify("Demo project upload failed: "+String((x as any).message||x))}}}>Add demo project</button>{list.map((p:Project)=><Row key={p.id}><img src={p.coverImage||imgPlaceholder(p.title)}/><b>{p.title}</b><span>{p.category}</span><select value={p.status} onChange={e=>update((d:AppData)=>({...d,projects:d.projects.map(x=>x.id===p.id?{...x,status:e.target.value as ProjectStatus,updates:[...x.updates,{date:new Date().toISOString().slice(0,10),status:e.target.value,note:'Status updated'}]}:x)}))}>{statuses.map(s=><option>{s}</option>)}</select><button onClick={()=>setEdit(p)}><Edit/></button><button onClick={()=>confirm('Delete project?')&&update((d:AppData)=>({...d,projects:d.projects.filter(x=>x.id!==p.id),activity:[`Deleted project ${p.title}`,...d.activity]}))}><Trash2/></button></Row>)}{edit&&<ProjectForm p={edit} close={()=>setEdit(null)} save={async(p:Project)=>{try{if(isSupabaseConfigured)await saveSupabaseProject(p);update((d:AppData)=>({...d,projects:d.projects.some(x=>x.id===p.id)?d.projects.map(x=>x.id===p.id?p:x):[p,...d.projects],activity:[`Saved project ${p.title}`,...d.activity]}));notify(isSupabaseConfigured?'Project uploaded to Supabase':'Project saved locally');setEdit(null)}catch(x){notify('Project upload failed: '+String((x as any).message||x))}}}/>}</Crud>}
function ProjectForm({p,save,close}:any){const[f,setF]=useState<Project>(p);return <Modal close={close}><h2>{f.title?'Edit':'Add'} Project</h2><FormInput f={f} setF={setF} fields={['title','clientName','year','link','deadline','revenue']}/><label>Category<select value={f.category} onChange={e=>setF({...f,category:e.target.value as Category})}>{cats.slice(1).map(c=><option>{c}</option>)}</select></label><label>Status<select value={f.status} onChange={e=>setF({...f,status:e.target.value as ProjectStatus})}>{statuses.map(s=><option>{s}</option>)}</select></label>{['description','problem','process','result'].map(k=><label>{k}<textarea value={(f as any)[k]} onChange={e=>setF({...f,[k]:e.target.value})}/></label>)}<label>Tags comma<input value={f.tags.join(', ')} onChange={e=>setF({...f,tags:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})}/></label><label>Tools comma<input value={f.tools.join(', ')} onChange={e=>setF({...f,tools:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})}/></label><UploadBox label="Cover image" set={v=>setF({...f,coverImage:v})}/><UploadBox label="Gallery images" multiple set={v=>setF({...f,galleryImages:[...f.galleryImages,v]})}/><label><input type="checkbox" checked={f.featured} onChange={e=>setF({...f,featured:e.target.checked})}/> Featured</label><label><input type="checkbox" checked={f.published} onChange={e=>setF({...f,published:e.target.checked})}/> Published</label><button className="secondary" onClick={()=>alert('Preview: '+f.title)}>Preview project before publishing</button><button className="primary" onClick={()=>f.title?save(f):alert('Title required')}>Save</button></Modal>}
function EnquiriesAdmin({data,update,notify}:any){const[q,setQ]=useState(''),[status,setStatus]=useState('All'),[sel,setSel]=useState<Enquiry|null>(null);const list=data.enquiries.filter((e:Enquiry)=>(status==='All'||e.status===status)&&(`${e.name} ${e.email} ${e.phone} ${e.business} ${e.number} ${e.service}`.toLowerCase().includes(q.toLowerCase())));function conv(e:Enquiry){const p=blankProject();p.title=e.business||e.name+' Project';p.description=e.description;p.clientName=e.name;p.status='Approved';p.published=false;update((d:AppData)=>({...d,projects:[p,...d.projects],enquiries:d.enquiries.map(x=>x.id===e.id?{...x,status:'Project Created'}:x),activity:[`Converted ${e.number} to project`,...d.activity]}));notify('Converted to project')}return <Crud title="Enquiry Management" search={q} setSearch={setQ}><select value={status} onChange={e=>setStatus(e.target.value)}><option>All</option>{eqStatuses.map(s=><option>{s}</option>)}</select>{list.map((e:Enquiry)=><Row key={e.id}><b>{e.number}</b><span>{e.name}</span><span>{e.email}</span><span>{e.phone}</span><span>{e.service}</span><select value={e.status} onChange={ev=>update((d:AppData)=>({...d,enquiries:d.enquiries.map(x=>x.id===e.id?{...x,status:ev.target.value as EnquiryStatus}:x)}))}>{eqStatuses.map(s=><option>{s}</option>)}</select><button onClick={()=>setSel(e)}><Eye/></button><button onClick={()=>conv(e)}>Convert</button></Row>)}{sel&&<Modal close={()=>setSel(null)}><h2>{sel.number}</h2><div className="cols"><Card><h3>Sender Details</h3><p><b>Name:</b> {sel.name}</p><p><b>Email:</b> {sel.email}</p><p><b>Phone:</b> {sel.phone}</p><p><b>Business:</b> {sel.business}</p></Card><Card><h3>Requirement</h3><p><b>Service:</b> {sel.service}</p><p><b>Budget:</b> {sel.budget}</p><p><b>Deadline:</b> {sel.deadline}</p><p><b>Status:</b> {sel.status}</p><p><b>Payment:</b> {sel.paymentStatus||'Unpaid'}</p><p><b>Amount:</b> {sel.paymentAmount||''}</p></Card></div><h3>Project Description</h3><p>{sel.description}</p>{sel.file&&<img className="preview" src={sel.file}/>}<h3>Internal Notes</h3>{sel.notes?.map((n:string)=><p>- {n}</p>)}<textarea placeholder="Add internal note" onBlur={e=>{const note=e.currentTarget.value;if(note)update((d:AppData)=>({...d,enquiries:d.enquiries.map(x=>x.id===sel.id?{...x,notes:[...x.notes,note]}:x)}))}}/><button onClick={()=>notify('Quotation marked as sent')}>Send quotation</button><button onClick={()=>update((d:AppData)=>({...d,enquiries:d.enquiries.map(x=>x.id===sel.id?{...x,status:'Completed'}:x)}))}>Mark completed</button></Modal>}</Crud>}
function TeamAdmin({data,update,notify}:any){const[edit,setEdit]=useState<TeamMember|null>(null);return <Crud title="Team Management" onAdd={()=>setEdit(blankMember())}>{data.team.sort((a:TeamMember,b:TeamMember)=>a.order-b.order).map((m:TeamMember)=><Row key={m.id}><img src={m.photo||imgPlaceholder(m.fullName||m.name)}/><b>{m.fullName||m.name}</b><span>{m.role}</span><span>{m.active?'Public':'Hidden'} • {m.featured?'Featured':'Standard'}</span><button onClick={()=>setEdit(m)}><Edit/></button><button onClick={()=>confirm('Delete member?')&&update((d:AppData)=>({...d,team:d.team.filter(x=>x.id!==m.id),activity:[`Deleted team member ${m.fullName||m.name}`,...d.activity]}))}><Trash2/></button></Row>)}{edit&&<TeamMemberForm member={edit} projects={data.projects} close={()=>setEdit(null)} notify={notify} save={(m:TeamMember)=>{update((d:AppData)=>({...d,team:d.team.some(x=>x.id===m.id)?d.team.map(x=>x.id===m.id?m:x):[m,...d.team],activity:[`Saved team member ${m.fullName||m.name}`,...d.activity]}));notify('Team profile saved');setEdit(null)}}/>}</Crud>}
function TeamMemberForm({member,projects,save,close,notify}:any){const[f,setF]=useState<TeamMember>({...member,socials:{...socialDefaults(),...(member.socials||{})}});const[err,setErr]=useState('');function setSoc(k:string,v:string){setF({...f,socials:{...f.socials,[k]:v}})}function cleanAndSave(){let socials:any={...f.socials};for(const k of Object.keys(socials)){const clean=normalizeUrl(socials[k],k==='email'?'email':k==='whatsapp'?'whatsapp':'url');if(socials[k]&&!clean){setErr(`Invalid ${socialMeta[k]?.[1]||k} value`);return}socials[k]=clean}const full=f.fullName||f.name;if(!full||!f.role){setErr('Full name and role are required.');return}save({...f,name:full,fullName:full,bio:f.shortBio||f.bio,shortBio:f.shortBio||f.bio,socials,email:f.email||socials.email,resumeUrl:f.resumeUrl||socials.resume,username:(f.username||full).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')})}return <Modal close={close}><h2>Team member profile</h2>{err&&<p className="error">{err}</p>}<div className="form"><label>Full name<input value={f.fullName||f.name} onChange={e=>setF({...f,fullName:e.target.value,name:e.target.value})}/></label><label>Username / slug<input value={f.username} onChange={e=>setF({...f,username:e.target.value})}/></label><label>Role<input value={f.role} onChange={e=>setF({...f,role:e.target.value})}/></label><label>Experience<input value={f.experience} onChange={e=>setF({...f,experience:e.target.value})}/></label><label>Location<input value={f.location} onChange={e=>setF({...f,location:e.target.value})}/></label><label>Email<input value={f.email} onChange={e=>setF({...f,email:e.target.value})}/></label><label>Phone number<input value={f.phone} onChange={e=>setF({...f,phone:e.target.value})}/></label><label>Join date<input type="date" value={f.joinDate} onChange={e=>setF({...f,joinDate:e.target.value})}/></label><label>Display order<input value={f.order} onChange={e=>setF({...f,order:Number(e.target.value)||999})}/></label><label>Availability<select value={f.availability} onChange={e=>setF({...f,availability:e.target.value as any})}>{['Available','Busy','On Leave','Not Available'].map(x=><option>{x}</option>)}</select></label><label>Short biography<textarea value={f.shortBio||f.bio} onChange={e=>setF({...f,shortBio:e.target.value,bio:e.target.value})}/></label><label>Long biography<textarea value={f.longBio} onChange={e=>setF({...f,longBio:e.target.value})}/></label><label>Skills comma<input value={f.skills.join(', ')} onChange={e=>setF({...f,skills:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})}/></label><label>Assigned projects<select multiple value={f.projects} onChange={e=>setF({...f,projects:[...e.target.selectedOptions].map(o=>o.value)})}>{projects.map((p:Project)=><option value={p.id}>{p.title}</option>)}</select></label><UploadBox label="Profile photo" set={v=>setF({...f,photo:v})}/><UploadAny label="Resume/CV file" set={v=>setF({...f,resumeUrl:v,socials:{...f.socials,resume:v}})}/>{Object.keys(socialMeta).filter(k=>k!=='resume').map(k=><label key={k}>{socialMeta[k][1]}<input value={(f.socials as any)[k]||''} onChange={e=>setSoc(k,e.target.value)} placeholder={k==='linkedin'?'https://www.linkedin.com/in/username':k==='github'?'https://github.com/username':k==='youtube'?'https://www.youtube.com/@username':''}/></label>)}<label><input type="checkbox" checked={f.active} onChange={e=>setF({...f,active:e.target.checked})}/> Show on public website</label><label><input type="checkbox" checked={f.featured} onChange={e=>setF({...f,featured:e.target.checked})}/> Featured team member</label></div><button className="secondary" onClick={()=>navigator.clipboard?.writeText(location.origin+'/#team/'+(f.username||f.id)).then(()=>notify('Profile link copied'))}>Copy profile link</button><button className="secondary" onClick={()=>alert('Public profile preview: '+(f.fullName||f.name))}>View public profile</button><button className="secondary" onClick={()=>alert('Preview: '+(f.fullName||f.name)+' • '+f.role)}>Preview profile before publishing</button><button className="primary" onClick={cleanAndSave}>Save member</button></Modal>}
function UploadAny({label,set}:any){const[err,setErr]=useState('');const[busy,setBusy]=useState(false);return <label>{label}<input type="file" accept=".pdf,.doc,.docx,image/*" onChange={async e=>{try{const file=e.target.files?.[0];if(!file)return;if(file.size>5*1024*1024)throw 'File must be below 5MB';setBusy(true);let url:string|null=null;if(isSupabaseConfigured){try{url=await uploadToSupabaseStorage(file,'resumes')}catch{url=null}}if(url){set(url)}else{const r=new FileReader();r.onload=()=>set(String(r.result));r.onerror=()=>setErr('Upload failed');r.readAsDataURL(file)}setErr('')}catch(x){setErr(String((x as any).message||x))}finally{setBusy(false)}}}/>{busy&&<p className="muted">Uploading...</p>}{err&&<p className="error">{err}</p>}</label>}
function ServicesAdmin({data,update,notify}:any){const[edit,setEdit]=useState<Service|null>(null);return <Crud title="Services Management" onAdd={()=>setEdit(blankService())}>{data.services.map((s:Service)=><Row><b>{s.name}</b><span>{s.price}</span><span>{s.active?'Active':'Inactive'}</span><button onClick={()=>setEdit(s)}><Edit/></button><button onClick={()=>confirm('Delete service?')&&update((d:AppData)=>({...d,services:d.services.filter(x=>x.id!==s.id)}))}><Trash2/></button></Row>)}{edit&&<EntityForm entity={edit} close={()=>setEdit(null)} save={(s:Service)=>{update((d:AppData)=>({...d,services:d.services.some(x=>x.id===s.id)?d.services.map(x=>x.id===s.id?s:x):[s,...d.services]}));notify('Service saved');setEdit(null)}} type="service"/>}</Crud>}
function ContentAdmin({data,update,notify}:any){const[edit,setEdit]=useState<ContentItem|null>(null);return <Crud title="Content Studio" onAdd={()=>setEdit({id:crypto.randomUUID(),title:'',type:'Social media posts',caption:'',hashtags:[],status:'Idea',image:'',dueDate:''})}>{data.content.map((c:ContentItem)=><Row><img src={c.image||imgPlaceholder(c.title)}/><b>{c.title}</b><span>{c.type}</span><span>{c.status}</span><button onClick={()=>setEdit(c)}><Edit/></button></Row>)}{edit&&<Modal close={()=>setEdit(null)}><h2>Content Item</h2><FormInput f={edit} setF={setEdit} fields={['title','type','caption','dueDate']}/><label>Status<select value={edit.status} onChange={e=>setEdit({...edit,status:e.target.value as any})}>{['Idea','In Design','Review','Approved','Published'].map(s=><option>{s}</option>)}</select></label><UploadBox label="Creative preview" set={v=>setEdit({...edit,image:v})}/><button className="primary" onClick={()=>{update((d:AppData)=>({...d,content:d.content.some(x=>x.id===edit.id)?d.content.map(x=>x.id===edit.id?edit:x):[edit,...d.content]}));notify('Content saved');setEdit(null)}}>Save</button></Modal>}</Crud>}
function SettingsAdmin({data,update,notify}:any){const[s,setS]=useState(data.settings);return <Page title="Settings" sub="Business, theme and notification preferences."><div className="form"><FormInput f={s} setF={setS} fields={['businessName','logo','ownerName','ownerProfile','email','phone','whatsapp','currency','paymentLink','upiId','paymentMerchant','paymentQrUrl']}/><UploadBox label="Upload business logo" set={v=>setS({...s,logo:v})}/>{s.logo&&String(s.logo).startsWith('data:')&&<img className="preview" src={s.logo}/>}<label>Theme<select value={s.theme} onChange={e=>setS({...s,theme:e.target.value})}><option>dark</option><option>light</option></select></label><label>Default project status<select value={s.defaultProjectStatus} onChange={e=>setS({...s,defaultProjectStatus:e.target.value})}>{statuses.map(x=><option>{x}</option>)}</select></label><label><input type="checkbox" checked={s.notifications} onChange={e=>setS({...s,notifications:e.target.checked})}/> Notifications</label><button className="primary" onClick={()=>{update((d:AppData)=>({...d,settings:s}));notify('Settings saved')}}>Save settings</button><button className="secondary" onClick={()=>{localStorage.clear();location.reload()}}>Reset demo data</button></div></Page>}
function EntityForm({entity,save,close,type}:any){const[f,setF]=useState<any>(entity);return <Modal close={close}><h2>{type} editor</h2><FormInput f={f} setF={setF} fields={type==='team'?['name','role','bio','experience']:['name','icon','description','price','deliveryTime','order']}/>{type==='team'?<><label>Skills comma<input value={f.skills.join(', ')} onChange={e=>setF({...f,skills:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})}/></label><UploadBox label="Profile photo" set={v=>setF({...f,photo:v})}/><label><input type="checkbox" checked={f.active} onChange={e=>setF({...f,active:e.target.checked})}/> Visible</label><label><input type="checkbox" checked={f.featured} onChange={e=>setF({...f,featured:e.target.checked})}/> Featured</label></>:<><label>Deliverables comma<input value={f.deliverables.join(', ')} onChange={e=>setF({...f,deliverables:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})}/></label><label><input type="checkbox" checked={f.active} onChange={e=>setF({...f,active:e.target.checked})}/> Active</label></>}<button className="primary" onClick={()=>f.name?save(f):alert('Name required')}>Save</button></Modal>}
function FormInput({f,setF,fields}:any){return <>{fields.map((k:string)=><label>{k}<input value={f[k]??''} onChange={e=>setF({...f,[k]:e.target.value})}/></label>)}</>}function UploadBox({label,set,multiple}:any){const[err,setErr]=useState('');const[busy,setBusy]=useState(false);return <label>{label}<input type="file" multiple={multiple} accept="image/*" onChange={async e=>{try{const files=[...(e.target.files||[])];setBusy(true);for(const file of files){let url:string|null=null;if(isSupabaseConfigured){try{url=await uploadToSupabaseStorage(file,'images')}catch{url=null}}set(url||await fileToData(file))}setErr('')}catch(x){setErr(String((x as any).message||x))}finally{setBusy(false)}}}/>{busy&&<p className="muted">Uploading...</p>}{err&&<p className="error">{err}</p>}</label>}
function Crud({title,onAdd,children,search,setSearch}:any){return <><div className="head"><h1>{title}</h1>{onAdd&&<button className="primary" onClick={onAdd}><Plus/>Add</button>}</div>{setSearch&&<div className="search"><Search/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search"/></div>}<div className="table">{children}</div></>}function Row(p:any){return <div className="row">{p.children}</div>}function Modal({children,close}:any){useEffect(()=>{const h=(e:KeyboardEvent)=>{if(e.key==='Escape')close()};addEventListener('keydown',h);return()=>removeEventListener('keydown',h)},[]);return <div className="modalBack" onMouseDown={close}><div className="modal" onMouseDown={e=>e.stopPropagation()}><button className="close" onClick={close}><X/></button>{children}</div></div>}
function Page({title,sub,children}:any){return <section className="page"><h1>{title}</h1><p>{sub}</p>{children}</section>}function Empty({text}:any){return <div className="empty"><ImageIcon/><p>{text}</p></div>}function Footer({data}:any){return <footer><b>{data.settings.businessName}</b><p>{data.settings.email} - {data.settings.phone}</p><p>Instagram - LinkedIn - GitHub - YouTube</p></footer>}
createRoot(document.getElementById('root')!).render(<App/>);


